#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long T;
    cin >> n >> T;
    vector<vector<long long>> clips(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> clips[i][j];
        }
    }

    sort(clips.begin(), clips.end());
    long long need = 0, count = 0, i = 0;
    bool possible = true;
    while (need < T) {
        long long best = need;
        while (i < n && clips[i][0] <= need) {
            best = max(best, clips[i][1]);
            i++;
        }
        if (best == need) {
            possible = false;
            break;
        }
        count++;
        need = best;
    }
    cout << (possible ? count : -1) << "\n";

    return 0;
}

