import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long T = Long.parseLong(next());
        long[][] clips = new long[(int) n][2];
        for (int i = 0; i < clips.length; i++) {
            for (int j = 0; j < clips[i].length; j++) {
                clips[i][j] = Long.parseLong(next());
            }
        }

        int total = (int) n;
        long[] keys = new long[total];
        for (int i = 0; i < total; i++) keys[i] = (clips[i][0] << 30) + clips[i][1];
        Arrays.sort(keys);
        long need = 0, count = 0;
        int i = 0;
        boolean possible = true;
        while (need < T) {
            long best = need;
            while (i < total && (keys[i] >> 30) <= need) {
                best = Math.max(best, keys[i] & ((1L << 30) - 1));
                i++;
            }
            if (best == need) {
                possible = false;
                break;
            }
            count++;
            need = best;
        }
        System.out.println(possible ? count : -1);
    }
}
